"""Generic helpers."""

import asyncio
import time

import typing as t

from . import _utils, _globals
from ._compat import contextlib
from .base import IClosable

__all__ = export = _utils.ExportList()


@export
@contextlib.asynccontextmanager
async def closing(obj: IClosable, *more_objs: IClosable) -> t.AsyncIterator[None]:
    """A context manager that closes one or more given closables on exit.

    This helper allows to avoid context manager nesting. Given closables are
    closed in reversed order (from last to first), so the order does matter
    when dependent objects are closed.

    :param obj:
        The object to be closed.

        It must implement :class:`IClosable` interface.

    :param `*more_objs`:
        More objects to be closed.
    """
    all_objs = tuple([obj]) + more_objs
    try:
        yield
    finally:
        for obj in reversed(all_objs):
            if not obj.is_closed():
                await obj.close()


@export
async def repeat_until_returns(
    factory: t.Callable[[], t.Awaitable],
    exception: t.Union[t.Type, t.Tuple[t.Type]] = None,
    initial_delay: float = 0.1,
    max_delay: float = 60.0,
    base: float = 2.0,
    timeout: float = None
) -> t.Optional[t.Any]:
    """Periodically run awaitable returned by *factory* function until it
    returns a value.

    This helper can be used to implement resilent services, when you need to
    retry failing operation at least few times before giving up. For example,
    when you need your API client to await for an API server when it is
    restarted.

    Uses exponential backoff algorithm to wait for a next attempt.

    :param factory:
        Factory function returning awaitable to be executed

    :param exception:
        Exception type (or tuple of exception types) to catch.

        Other exceptions will be re-raised by this function. However, if none
        given, then a default :exc:`Exception` class will be used, effectively
        catching all exceptions.

    :param initial_delay:
        Time to wait before first retry.

    :param max_delay:
        Maximal delay to wait before next retry.

        Once this is reached, exponential backoff formula is no longer used and
        delay time before next retries will be kept at this value.

    :param base:
        Exponential base to be used.

        The formula of calculating delay time before next retry is following:

            Delay = min(MaxDelay, InitialDelay * pow(Base, RetryNum))

        Where:

            MaxDelay = *max_delay*
            InitialDelay = *initial_delay*
            Base = *base*
            RetryNum = number of retries so far

    :param timeout:
        Global timeout.

        If this is set and function is executed for longer time than given
        timeout expressed in seconds, then function termianates and re-raises
        last catched exception.

        Please note that effective timeout might be greater, as it depends on
        other parameters this function is called with. However, it will not be
        greater than ``timeout + max_delay``.

        .. versionadded:: 0.10.0
    """
    retry_num = 0
    exception = exception or Exception
    start_time = time.monotonic()
    while True:
        awaitable = factory()
        try:
            return await awaitable
        except exception as e:
            delay = min(max_delay, initial_delay * (base**retry_num))
            retry_num += 1
            time_taken = time.monotonic() - start_time
            if timeout is not None and time_taken > timeout:
                raise
            _globals.logger.debug(
                'Awaitable %r got an exception (type=%r, msg=%r), retrying (%d) in %1.3f seconds...',
                awaitable, e.__class__.__qualname__, str(e), retry_num, delay
            )
            await asyncio.sleep(delay)
